import{_ as t,o as i,c as o,ag as r}from"./chunks/framework.DXGyWiRo.js";const p=JSON.parse('{"title":"GitHub Protection Settings","description":"","frontmatter":{},"headers":[],"relativePath":"github-protection.md","filePath":"github-protection.md","lastUpdated":1777882948000}'),a={name:"github-protection.md"};function n(s,e,c,l,d,u){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="github-protection-settings" tabindex="-1">GitHub Protection Settings <a class="header-anchor" href="#github-protection-settings" aria-label="Permalink to &quot;GitHub Protection Settings&quot;">​</a></h1><p>This repository uses files to enforce as much as possible, but several settings must be configured manually in the GitHub UI.</p><h2 id="branch-protection" tabindex="-1">Branch Protection <a class="header-anchor" href="#branch-protection" aria-label="Permalink to &quot;Branch Protection&quot;">​</a></h2><p>For the <code>main</code> branch, enable:</p><ul><li><p>[ ] <strong>Require a pull request before merging</strong></p><ul><li>[ ] Require approvals: minimum 1</li><li>[ ] Dismiss stale PR approvals when new commits are pushed</li><li>[ ] Require review from CODEOWNERS for affected paths</li><li>Note: Architectural changes (as defined in <code>GOVERNANCE.md</code>) require 2 approvals in practice, enforced by CODEOWNERS rules and maintainer discretion</li></ul></li><li><p>[ ] <strong>Require status checks to pass before merging</strong></p><ul><li>[ ] Require branches to be up to date before merging</li><li>Required checks (from <code>ci.yml</code>): <ul><li><code>backend-check</code></li><li><code>frontend-check</code></li><li><code>push-proxy-check</code></li><li><code>docker-validate</code></li><li><code>build-release</code></li></ul></li><li>Required checks (from <code>security.yml</code>): <ul><li><code>codeql</code></li><li><code>cargo-audit-backend</code></li><li><code>cargo-audit-push-proxy</code></li><li><code>cargo-deny</code></li><li><code>npm-audit</code></li><li><code>dependency-review</code></li></ul></li><li>Required checks (from <code>dco.yml</code>): <ul><li><code>dco-check</code></li></ul></li><li><strong>Note:</strong> The <code>cargo-deny</code> and <code>codeql</code> checks may be slow. They can be marked as &quot;not required&quot; initially while the project stabilizes.</li></ul></li><li><p>[ ] <strong>Require conversation resolution before merging</strong></p></li><li><p>[ ] <strong>Do not allow bypassing the above settings</strong> — admins must not be able to push directly to <code>main</code> or merge without checks</p></li></ul><h2 id="rulesets-recommended-alternative-to-branch-protection" tabindex="-1">Rulesets (Recommended Alternative to Branch Protection) <a class="header-anchor" href="#rulesets-recommended-alternative-to-branch-protection" aria-label="Permalink to &quot;Rulesets (Recommended Alternative to Branch Protection)&quot;">​</a></h2><p>If using GitHub rulesets instead of classic branch protection:</p><ul><li>Target branch: <code>main</code></li><li>Restrict creations, updates, and deletions</li><li>Require pull requests with CODEOWNERS review</li><li>Require status checks (list above)</li><li>Block force pushes</li></ul><h2 id="protected-tags" tabindex="-1">Protected Tags <a class="header-anchor" href="#protected-tags" aria-label="Permalink to &quot;Protected Tags&quot;">​</a></h2><p>Protect version tags to prevent accidental deletion or overwrite:</p><ul><li>Pattern: <code>v*</code></li><li>Restrict create, update, and delete to maintainers</li></ul><h2 id="codeowners" tabindex="-1">CODEOWNERS <a class="header-anchor" href="#codeowners" aria-label="Permalink to &quot;CODEOWNERS&quot;">​</a></h2><p><code>CODEOWNERS</code> is already in place. Ensure the file is accurate and reviewers are active.</p><h2 id="dco-requirement" tabindex="-1">DCO Requirement <a class="header-anchor" href="#dco-requirement" aria-label="Permalink to &quot;DCO Requirement&quot;">​</a></h2><p>The <code>.github/workflows/dco.yml</code> workflow enforces signed-off commits. In branch protection, mark the <code>DCO</code> check as <strong>required</strong>. Without this, unsigned commits can be merged even if the DCO workflow fails.</p><h2 id="secret-scanning-and-push-protection" tabindex="-1">Secret Scanning and Push Protection <a class="header-anchor" href="#secret-scanning-and-push-protection" aria-label="Permalink to &quot;Secret Scanning and Push Protection&quot;">​</a></h2><p>Enable in the repository settings:</p><ul><li>[ ] <strong>Secret scanning</strong> — Detects accidentally committed secrets</li><li>[ ] <strong>Push protection</strong> — Blocks pushes that contain secrets</li></ul><p>These cannot be enabled via repository files and must be turned on in the GitHub UI under <strong>Settings &gt; Security &gt; Code security and analysis</strong>.</p><h2 id="dependabot" tabindex="-1">Dependabot <a class="header-anchor" href="#dependabot" aria-label="Permalink to &quot;Dependabot&quot;">​</a></h2><p><a href="../.github/dependabot.yml">Dependabot configuration</a> is in place. Enable in the GitHub UI:</p><ul><li>[ ] <strong>Dependabot alerts</strong> — Notifications for vulnerable dependencies</li><li>[ ] <strong>Dependabot security updates</strong> — Automatic PRs for security fixes</li></ul><h2 id="package-permissions" tabindex="-1">Package Permissions <a class="header-anchor" href="#package-permissions" aria-label="Permalink to &quot;Package Permissions&quot;">​</a></h2><p>For container images published to GHCR:</p><ul><li>[ ] Ensure <code>GITHUB_TOKEN</code> has <code>packages: write</code> permission in workflows</li><li>[ ] Configure package visibility (public or internal) under <strong>Packages</strong> settings</li><li>[ ] Link packages to this repository</li></ul><h2 id="security-advisories" tabindex="-1">Security Advisories <a class="header-anchor" href="#security-advisories" aria-label="Permalink to &quot;Security Advisories&quot;">​</a></h2><ul><li>[ ] Enable private vulnerability reporting under <strong>Settings &gt; Security &gt; Reporting</strong></li><li>[ ] Designate maintainers as security contacts</li></ul>',27)])])}const g=t(a,[["render",n]]);export{p as __pageData,g as default};
